We need a bunch of helper functions before we can get to the real deal.
First, we need a function that checks if the basic variable inputs make sense.

matchInputsSimple &lt;- function(key,year,agep,gasp,grpip,JWAP,JWDP,jwmnp,sex,fer,hhl,sch,schl,geog,gsubset){
  if(!all(is.logical(c(agep,gasp,grpip,JWAP,JWDP,jwmnp,sex,fer,hhl,sch,schl)))){
    stop("Each of the non-filtering variables takes a T/F value")
  }
  if(!is.character(key)){
    stop("The census key must be entered as a string")
  }
  geog &lt;- tolower(geog)
  if(!geog %in% c("state","region","division")){
    stop("The geography options are state, region, and division.")
  }
}

Next, we need to check if the user has selected at least one numeric and one categorical variable.

atLeastOne &lt;- function(numVars,catVars){
  if (!any(numVars)) {
    stop("Choose at least one numeric variable.")}
  if (!any(catVars)) {
    stop("Choose at least one categorical variable.")
  }
}

Now we’ll create the string for the selected (and prescribed) variables.

setVarString &lt;- function(numVars,catVars){
  selectedNums &lt;- names(numVars)[numVars]
  selectedCats &lt;- names(catVars)[catVars]
  allRequested &lt;- unique(c("PWGTP", selectedNums, selectedCats))
  realVars &lt;- toupper(paste(allRequested, collapse=","))
}

Now we need to deal with the geography. The rubric implies a difference between the years 2021/2022 and 2023/2024 in terms of the st/state variable, however when I attempted to account for this I discovered that it was not the case on my end. If you go back through my commits you can see when I figured this out.
Anyway, let’s start by getting a list of the codes for the geography levels.

grabCodes&lt;-function(){
  check&lt;-varLists[[1]]
  regions&lt;-check$REGION
  values&lt;-regions$values
  regionCodes&lt;-values$item
  states&lt;-check$ST
  values&lt;-states$values
  stateCodes&lt;-values$item
  divisions&lt;-check$DIVISION
  values&lt;-divisions$values
  divisionCodes&lt;-values$item
  geogCodes&lt;-list("regionCodes"=names(regionCodes),"stateCodes"=names(stateCodes),"divisionCodes"=names(divisionCodes))
  return(geogCodes)
}
geogCodes &lt;- grabCodes()

Moving on, let’s check to make sure that the inputted geography level matches the setting.

matchGeogSubsets &lt;- function(geog,gsubset){if(geog == "region"){
  options&lt;-geogCodes$regionCodes
  options[[6]]&lt;-"All"}
  if(geog == "division"){
    options&lt;-geogCodes$divisionCodes
    options[[11]]&lt;-"All"}
  if(geog == "state"){
    options&lt;-geogCodes$stateCodes
    options[[53]]&lt;-"All"}

  if(!gsubset %in% options){
    stop(paste0("The ", geog," code selected does not exist, choose from: ",paste(options,collapse=",")))}}

Now we need to account for the “all” option. I think you can do this with the asterisk, but in my fevered attempts to fix the st/state issue, I changed it to this method, and it works, so I’m not changing it again.

allowForAll &lt;- function(geog,gsubset){
  if (gsubset == "All"){
    if(geog == "region"){gsubset &lt;-allRegions}
    else if (geog == "division"){gsubset &lt;- allDivisions}
    else if (geog == "state"){gsubset &lt;- allStates}
  }
  else {gsubset &lt;- gsubset}
}

Now we’ll set up the string for the geography settings.

setGeogString &lt;- function(geog,gsubset){
  geogString &lt;- paste0(geog,":",gsubset)
}

Now I need to do some final set-up for fixing up the final tibble.
First, we’ll ask AI to help us with the midpoint function:

get_time_midpoint &lt;- function(time_ranges, format_12hr=TRUE) {
  # 1. Standardize "p.m." -&gt; "PM" and "a.m." -&gt; "AM"
  cleaned &lt;- gsub("p\\.m\\.", "PM", time_ranges, ignore.case=TRUE)
  cleaned &lt;- gsub("a\\.m\\.", "AM", cleaned, ignore.case=TRUE)

  # 2. Split start and end
  split_times &lt;- strsplit(cleaned, "\\s+to\\s+")
  start_str &lt;- sapply(split_times, `[`, 1)
  end_str   &lt;- sapply(split_times, `[`, 2)

  # 3. Parse with anchored dummy date
  today &lt;- Sys.Date()
  start_time &lt;- as.POSIXct(paste(today, start_str), format="%Y-%m-%d %I:%M %p")
  end_time   &lt;- as.POSIXct(paste(today, end_str),   format="%Y-%m-%d %I:%M %p")

  # 4. Handle overnight boundary crossover
  overnight &lt;- !is.na(start_time) & !is.na(end_time) & (end_time &lt; start_time)
  end_time[overnight] &lt;- end_time[overnight]+(24 * 3600)

  # 5. Compute midpoint
  midpoint &lt;- start_time+(end_time - start_time) / 2

  # 6. Format output (12-hour AM/PM vs 24-hour)
  if (format_12hr) {
    return(format(midpoint, "%I:%M %p")) # Returns e.g. "06:37 PM"
  } else {
    return(format(midpoint, "%H:%M"))    # Returns e.g. "18:37"
  }
}

And now we apply this to the values for JWAP and JWDP, which are unfortunately not the same.

getJWAPPED&lt;-function(){
  check&lt;-varLists[[1]]
  JWAP1&lt;-check$JWAP
  values&lt;-JWAP1$values
  JWAP&lt;-unlist(values$item)
  ids&lt;-names(JWAP)
  JWAP&lt;-cbind("JWAP"=ids,"times"=JWAP)
  JWAP[,2]&lt;-get_time_midpoint(JWAP[,2])
  JWAP&lt;-as_tibble(JWAP)
  return(JWAP)
}

getJWDPPED&lt;-function(){
  check&lt;-varLists[[1]]
  JWDP1&lt;-check$JWDP
  values&lt;-JWDP1$values
  JWDP&lt;-unlist(values$item)
  ids&lt;-names(JWDP)
  JWDP&lt;-cbind("JWDP"=ids,"times"=JWDP)
  JWDP[,2]&lt;-get_time_midpoint(JWDP[,2])
  JWDP&lt;-as_tibble(JWDP)
  return(JWDP)
}

JWAPVals&lt;-getJWAPPED()
JWDPVals&lt;-getJWDPPED()

Finally, we pull on all these functions to create the opposite of a helper function: a harmer function.

apiHarmer &lt;- function(key,year=2024,agep=T,gasp=F,grpip=F,JWAP=F,JWDP=F,jwmnp=F,sex=T,fer=F,hhl=F,sch=F,schl=F,geog="region",gsubset="2"){

  geogCodes &lt;- grabCodes()
  JWAPVals&lt;-getJWAPPED()
  JWDPVals&lt;-getJWDPPED()

  allStates &lt;- paste(geogCodes$stateCodes, collapse=",")
  allRegions &lt;- paste(geogCodes$regionCodes, collapse=",")
  allDivisions &lt;- paste(geogCodes$divisionCodes, collapse=",")

  numVars &lt;- c(agep=agep, gasp=gasp,grpip=grpip,JWAP=JWAP,JWDP=JWDP,jwmnp=jwmnp)
  catVars &lt;- c(sex=sex,fer=fer,hhl=hhl,sch=sch,schl=schl)

  matchInputsSimple(key,year,agep,gasp,grpip,JWAP,JWDP,jwmnp,sex,fer,hhl,sch,schl,geog,gsubset)

  atLeastOne(numVars,catVars)

  varString &lt;- setVarString(numVars,catVars)

  matchGeogSubsets(geog,gsubset)

  gsubset&lt;-allowForAll(geog,gsubset)

  geogString &lt;- setGeogString(geog,gsubset)

  censusUrl &lt;- paste0(
    "https://api.census.gov/data/", year, "/acs/acs1/pums",
    "?get=", varString,
    "&for=", geogString,
    "&key=", key
  )

  request &lt;- GET(
    url=censusUrl
  )
  rawStats &lt;- content(request, "text", encoding="UTF-8")
  parsedStats &lt;- fromJSON(rawStats)
  censusPull &lt;- as_tibble(parsedStats)
  colnames(censusPull) &lt;- censusPull[1, ]
  censusPull &lt;- censusPull[-1, , drop=FALSE]

  # Here I'm joining the output with my JWAPVals tibble, so that I can swap out the time codes for the actual times
  if ("JWAP" %in% names(censusPull)) {
    censusPull &lt;- censusPull |&gt;
      left_join(JWAPVals, by="JWAP") |&gt; 
      mutate(JWAP=times) |&gt; # here's where I do that swap
      select(-times)}    # now I'm removing the leftovers of the join

  # and now I repeat the process for JWDP, which unfortunately has different values from JWAP
  if ("JWDP" %in% names(censusPull)) {
    censusPull &lt;- censusPull |&gt;
      left_join(JWDPVals, by="JWDP") |&gt;
      mutate(JWDP=times) |&gt;
      select(-times)}

  censusPull &lt;- censusPull |&gt;
    mutate(across(any_of(c("PWGTP", "GASP", "AGEP", "GRPIP", "JWMNP")), as.double))

  yearKey &lt;- paste0("y",year)
  yearMeta &lt;- varLists[[yearKey]]

  selectedCats &lt;- names(catVars)[catVars]

  for (cat_var in selectedCats) {
    cat_upper &lt;- toupper(cat_var)

    meta_key &lt;- if (cat_upper %in% names(yearMeta)) cat_upper else if (cat_var %in% names(yearMeta)) cat_var else NULL

    if (cat_upper %in% names(censusPull) && !is.null(meta_key)) {
      valItems &lt;- yearMeta[[meta_key]]$values$item
      if (!is.null(valItems)) {
        levelsVec &lt;- as.character(names(valItems))
        labelsVec &lt;- unname(unlist(valItems))

        censusPull &lt;- censusPull |&gt;
          mutate(!!cat_upper := factor(.data[[cat_upper]], levels=levelsVec, labels=labelsVec))
      }
    }
  }

  class(censusPull) &lt;- c("census", class(censusPull))

  return(censusPull)

}

Combining Years
This helper function allows for us to call multiple years, using the original apiHarmer function, and a built-in helper function this time.

censusAPIMultiyear &lt;- function(key,
                               Y2021=FALSE, Y2022=FALSE, Y2023=FALSE, Y2024=TRUE, 
                               agep=TRUE,
                               gasp=FALSE, grpip=FALSE, JWAP=FALSE, JWDP=FALSE, jwmnp=FALSE, 
                               sex=TRUE, 
                               fer=FALSE, hhl=FALSE, sch=FALSE, schl=FALSE, 
                               geog="STATE", gsubset="01") {

  puller &lt;- function(yearN) {
    block &lt;- apiHarmer(
      key=key, 
      year=yearN, 
      agep=agep, gasp=gasp, grpip=grpip, JWAP=JWAP, JWDP=JWDP, jwmnp=jwmnp,
      sex=sex, fer=fer, hhl=hhl, sch=sch, schl=schl,
      geog=geog, gsubset=gsubset
    )
    block$Year &lt;- yearN
    return(block)
  }

  dataList &lt;- list()

  if (Y2021) { dataList[["2021"]] &lt;- puller(2021) }
  if (Y2022) { dataList[["2022"]] &lt;- puller(2022) }
  if (Y2023) { dataList[["2023"]] &lt;- puller(2023) }
  if (Y2024) { dataList[["2024"]] &lt;- puller(2024) }

  if (length(dataList) == 0) {
    stop("Choose at least 1 year.")
  }

  comboYears &lt;- bind_rows(dataList)

  class(comboYears) &lt;- c("census", class(comboYears))
  return(comboYears)
}

Numerical Summaries
Moving on from the API Call itself, it’s time to create our summary function.

summary.census &lt;- function(census,
                           numerics=c("AGEP","GASP","GRPIP","JWMNP"),
                           categorics=c("SEX","FER","HHL","SCH","SCHL")){

    # First, let's check to make sure all of our inputs match again.

    matchInputs2 &lt;- function(census,numerics,categorics){
    if(!class(census)[1] == "census"){
      stop("Census object must be of the Census class.")
    }
    if(!is.atomic(numerics)){
      stop("The numeric variables must be in a atomic vector")
    }
    if(!is.atomic(categorics)){
      stop("The categorical variables must be in a atomic vector")
    }
    if (!all(sapply(numerics, is.character))){
      stop("The items of the numeric variable list must be the string names of the variables.")
    }
    if (!all(sapply(categorics, is.character))){
      stop("The items of the cateogrical variable list must be the string names of the variables.")}}

    # here's where we actually run that
    matchInputs2(census,numerics,categorics)

    # Next up, we'll check the selected variables against the census variables and the ones we can actually summarize here (no times or pgtwp)
    varsInCensus &lt;- function(census,numerics,categorics){
      potVars &lt;- colnames(census)
      allPotVars &lt;- c("AGEP","GASP","GRPIP","JWMNP","SEX","FER","HHL","SCH","SCHL")
      potVars &lt;- potVars[potVars %in% allPotVars]
      numerics &lt;- numerics[numerics %in% potVars]
      categorics &lt;- categorics[categorics %in% potVars]
      if(is_empty(numerics) & is_empty(categorics)){
        stop("No valid variables selected")}
      endVars &lt;- list("num"=numerics,"cat"=categorics)
      return(endVars)}

    # here's where we actually run that helper function
    endVars&lt;-varsInCensus(census,numerics,categorics)  
    numerics&lt;-endVars$num
    categorics&lt;-endVars$cat

    # Now I'm splitting the census into the numeric and categorical variable parts.
    numCensus &lt;- select(census,all_of(numerics))
    catCensus &lt;- select(census,all_of(categorics))

    # From that, I'm using sapply to get the mean and sd of every selected numerical variable.
    numSum &lt;- data.frame(
      variable=names(numCensus),
      mean=sapply(numCensus, mean, na.rm=TRUE),
      sd=sapply(numCensus, sd, na.rm=TRUE),
      row.names=NULL)

    # This was the worst part. There is probably a more efficient way of doing this, but this is what I came up with     after a lot of googling.
    catSum &lt;- do.call(rbind, lapply(names(catCensus), function(var) {
                              counts &lt;- table(catCensus[[var]], useNA="ifany")
                              data.frame(variable=var,level=names(counts),count=as.vector(counts),row.names=NULL)}))

    # Now we combine those two into a final list.
    finSum &lt;- list("Numerical Variables"=numSum,"Categorical Variables"=catSum)
    return(finSum)
}
